<template>
  <div class="item-loan">
    <table class="table table-sm table-hover table-stripped mt-1">
      <thead>
        <tr style="font-size: 10pt; font-weight: bold">
          <td colspan="6">Capital financiado</td>
          <td colspan="4" class="text-right">
            {{ convertMoney(currentLoan.amount) }}
          </td>
        </tr>
        <tr style="font-size: 10pt; font-weight: bold">
          <td colspan="6">Juros</td>
          <td colspan="4" class="text-right">
            {{ convertMoney(currentLoan.interestRate * currentLoan.amount) }}
          </td>
        </tr>
        <tr style="font-size: 10pt; font-weight: bold">
          <td colspan="6">Total Da Dívida</td>
          <td colspan="4" class="text-right">
            {{
              convertMoney(
                currentLoan.amount * currentLoan.interestRate +
                  currentLoan.amount
              )
            }}
          </td>
        </tr>
      </thead>
      <thead>
        <tr style="font-size: 10pt" class="bg-secondary text-white">
          <th>Ordem</th>
          <th class="text-right">Capital</th>
          <th class="text-right">Juros</th>
          <th class="text-right">Prestação</th>
          <th class="text-right">Saldo Devedor</th>
          <th class="text-right">Dias em atrazo</th>
          <th class="text-right">Juros de mora</th>
          <th class="text-right">Total a pagar</th>
          <th class="text-right">Vencimento</th>
          <th class="text-center">Acções</th>
        </tr>
      </thead>
      <tbody>
        <tr
          v-for="amortization in customerLoanAmortization"
          :key="amortization.id"
          style="font-size: 10pt; cursor: pointer"
        >
          <td>{{ amortization.installmentOrder }}</td>
          <td
            v-money-format="amortization.amortization"
            class="text-right"
          ></td>
          <td v-money-format="amortization.rateAmount" class="text-right"></td>
          <td v-money-format="amortization.installment" class="text-right"></td>
          <td class="text-right">
            <span v-if="amortization.remainingBalance !== undefined && amortization.remainingBalance !== null">
              {{ convertMoney(amortization.remainingBalance) }}
            </span>
            <span v-else class="text-muted">-</span>
          </td>
          <td class="text-right">{{ amortization.lateDays }}</td>
          <td class="text-right">
            {{
              amortization.status === -1
                ? convertMoney(totalAmortizationForfeit)
                : convertMoney(calculateForfeit(amortization))
            }}
          </td>
          <td class="text-right">
            {{
              amortization.status === -1
                ? convertMoney(getTotalDebt(amortization))
                : convertMoney(
                    amortization.latePaymentInterest + amortization.installment
                  )
            }}
          </td>
          <td v-date-format="amortization.dueDate" class="text-right"></td>
          <td class="text-center">
            <b-row class="text-center">
              <b-col
                v-if="amortization.status === 0"
                @click="addPayment(amortization)"
                ><b class="text-primary"
                  ><b-icon icon="credit-card" aria-hidden="true"></b-icon>
                  Pagar</b
                ></b-col
              >
              <b-col v-else-if="amortization.status === 1"
                ><b class="text-success" @click="previewReceipt(amortization)"
                  ><b-icon
                    icon="calendar2-check-fill"
                    aria-hidden="true"
                  ></b-icon>
                  Pago</b
                ></b-col
              >
              <b-col v-else-if="amortization.status === -1"
                ><b class="text-danger" @click="payDebt()"
                  ><b-icon
                    icon="calendar2-check-fill"
                    aria-hidden="true"
                  ></b-icon>
                  Pago parcialmente</b
                ></b-col
              >
            </b-row>
          </td>
        </tr>
      </tbody>
    </table>

    <b-modal
      hide-footer
      size="md"
      scrollable
      ref="place-payment"
      title="Adicionar pagamento"
    >
      <div>
        <b-overlay :show="isLoading" rounded="sm">
          <b-row
            ><b-col
              ><small>Data de pagamento</small>
              <b-form-datepicker
                v-model="paymentDate"
                :disabled="paymentMethod == 7"
                size="sm"
                class="mt-2 mb-2"
              ></b-form-datepicker>
            </b-col>
            <b-col>
              <small>Confirmativo pagamento</small>
              <b-form-file
                accept="*"
                @change="onFileChange"
                class="mt-2 mb-2 mt-2"
                size="sm"
              ></b-form-file>
            </b-col>
          </b-row>
          <b-row>
            <b-col
              ><b-progress
                :value="uploadValue"
                :max="100"
                show-progress
                animated
                class="mt-1 mb-1"
                v-if="uploadValue > 0"
              ></b-progress
            ></b-col>
          </b-row>
          <b-row>
            <b-col
              ><small>Meio de pagamento</small>
              <b-form-select
                class="mt-2"
                v-model="paymentMethod"
                :options="options"
                size="sm"
              ></b-form-select
            ></b-col>
            <b-col
              ><small>Referência de pagamento</small>
              <b-form-group label-for="payment_reference" class="mt-1">
                <b-form-input
                  type="text"
                  :disabled="paymentMethod == 7 || paymentMethod == 1"
                  size="sm"
                  v-model="paymentReference"
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <table
            class="table table-sm table-hover table-stripped mt-1 text-secondary"
          >
            <thead>
              <tr
                style="font-size: 12pt; font-weight: bold"
                class="text-secondary"
              >
                <th colspan="4">Valor da Prestação</th>
                <th colspan="2" class="text-right">
                  {{ convertMoney(currentAmortization.installment) }}
                </th>
              </tr>
              <tr style="font-size: 12pt; font-weight: bold">
                <th colspan="4">Dias de atrazo</th>
                <th colspan="2" class="text-right">{{ diffDays }} dias</th>
              </tr>
              <tr
                style="font-size: 12pt; font-weight: bold"
                class="text-secondary"
              >
                <th colspan="4">Juros de mora: {{ company.forfeit }}%</th>
                <th colspan="2" class="text-right">
                  {{ convertMoney(forfeitValue) }}
                </th>
              </tr>
              <tr
                style="font-size: 12pt; font-weight: bold"
                class="text-secondary"
              >
                <th colspan="4">TOTAL A PAGAR</th>
                <th colspan="2" class="text-right">
                  {{ convertMoney(total2Pay) }}
                </th>
              </tr>
            </thead>
          </table>
          <b-row>
            <b-col
              ><small>Valor a pagar</small>
              <b-form-group label-for="amount_received" class="mt-1">
                <b-form-input
                  type="number"
                  size="sm"
                  step="any"
                  :min="10"
                  v-model="amountReceived"
                ></b-form-input> </b-form-group
            ></b-col>
            <b-col
              ><small>Saldo devedor</small>
              <b-form-group label-for="debit_balance" class="mt-1">
                <b-form-input
                  type="number"
                  size="sm"
                  step="any"
                  v-model="debitBalance"
                  disabled
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <b-row v-if="paymentMethod == 7">
            <b-col
              ><small>Número Vodacom válido</small>
              <b-form-group label-for="vodacomNumber" class="mt-2">
                <b-form-input
                  type="number"
                  size="sm"
                  v-model="phoneNumber"
                ></b-form-input> </b-form-group></b-col
          ></b-row>
          <b-row>
            <b-col
              ><b-button
                @click="finalizepayment()"
                v-if="paymentMethod != 7"
                :disabled="isLoading"
                block
                size="sm"
                variant="secondary"
                >Submeter</b-button
              >
              <b-button
                @click="payViaMpesa()"
                v-else
                :disabled="isLoading"
                block
                size="sm"
                variant="secondary"
                >Pagar via M-Pesa</b-button
              >
            </b-col>
          </b-row>
        </b-overlay>
      </div>
    </b-modal>

    <b-modal
      hide-footer
      size="md"
      scrollable
      ref="place-debt-payment"
      title="Adicionar pagamento"
    >
      <div>
        <b-overlay :show="isLoading" rounded="sm">
          <b-row
            ><b-col
              ><small>Data de pagamento</small>
              <b-form-datepicker
                v-model="paymentDate"
                :disabled="paymentMethod == 7"
                size="sm"
                class="mt-2 mb-2"
              ></b-form-datepicker>
            </b-col>
            <b-col>
              <b-form-file
                accept="*"
                @change="onFileChange"
                class="mt-2 mb-2"
                size="sm"
              ></b-form-file>
            </b-col>
          </b-row>
          <b-row>
            <b-col
              ><b-progress
                :value="uploadValue"
                :max="100"
                show-progress
                animated
                class="mt-1 mb-1"
                v-if="uploadValue > 0"
              ></b-progress
            ></b-col>
          </b-row>
          <b-row>
            <b-col
              ><small>Meio de pagamento</small>
              <b-form-select
                class="mt-2"
                v-model="paymentMethod"
                :options="options"
                size="sm"
              ></b-form-select
            ></b-col>
            <b-col
              ><small>Referência de pagamento</small>
              <b-form-group label-for="payment_reference" class="mt-1">
                <b-form-input
                  type="text"
                  :disabled="paymentMethod == 7 || paymentMethod == 1"
                  size="sm"
                  v-model="paymentReference"
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <b-row>
            <b-col
              ><small>Valor a pagar</small>
              <b-form-group label-for="amount_received" class="mt-1">
                <b-form-input
                  type="number"
                  size="sm"
                  step="any"
                  :min="10"
                  v-model="amountReceived"
                ></b-form-input> </b-form-group
            ></b-col>
            <b-col
              ><small>Saldo devedor</small>
              <b-form-group label-for="debit_balance" class="mt-1">
                <b-form-input
                  type="number"
                  size="sm"
                  step="any"
                  v-model="debitBalance"
                  disabled
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <b-row v-if="paymentMethod == 7">
            <b-col
              ><small>Número Vodacom válido</small>
              <b-form-group label-for="vodacomNumber" class="mt-2">
                <b-form-input
                  type="number"
                  size="sm"
                  v-model="phoneNumber"
                ></b-form-input> </b-form-group></b-col
          ></b-row>
          <b-row>
            <b-col
              ><b-button
                @click="finalizeDebtpayment()"
                v-if="paymentMethod != 7"
                :disabled="isLoading"
                block
                size="sm"
                variant="secondary"
                >Submeter</b-button
              >
              <b-button
                @click="payDebtViaMpesa()"
                v-else
                :disabled="isLoading"
                block
                size="sm"
                variant="secondary"
                >Pagar via M-Pesa</b-button
              >
            </b-col>
          </b-row>
        </b-overlay>
      </div>
    </b-modal>
  </div>
</template>
<script>
import { mapGetters } from "vuex";
import axios from "axios";
import firebase from "firebase";
import MoneyFormat from "@/utils/moneyFormat";
import logs from "@/utils/logs";
import companyLogo from "@/utils/companyLogo";
// PDF Generator
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;
import moment from "moment";
import DateFormat from "@/utils/dateFormat";
import AmmortizationPlan from "@/utils/amortizationPlan";

export default {
  name: "item-loan",

  data: () => ({
    customerLoanAmortization: [],
    loanDebts: [],
    currentDebt: [],
    totalDebtAmount: 0,
    paymentReference: "",
    debitBalance: 0,
    amountReceived: 0,
    paymentDate: moment().format("YYYY-MM-DD"),
    phoneNumber: "",
    amortizationLoanId: 0,
    currentAmortization: {},
    installmentOrder: 0,
    diffDays: 0,
    forfeitValue: 0,
    total2Pay: 0,

    paymentMethod: 1,

    totalAmortizationForfeit: 0,
    paidAmortizations: 0,
    receiptUrl: "",
    documentName: "",
    selectedFile: "",
    uploadValue: 0,

    options: [
      { value: 1, text: "Boca do Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "M-Pesa USSD" },
      { value: 7, text: "M-Pesa Open API" },
      { value: 8, text: "E-Mola" },
    ],
    today: moment(),
  }),

  props: ["currentLoan"],

  created() {
    this.getAmortizationLoans();
    this.getLoanDebts();
  },

  watch: {
    paymentMethod: function () {
      if (this.paymentMethod != 1) {
        this.paymentReference = "";
      }
    },
    amountReceived: function () {
      this.debitBalance =
        this.currentAmortization.status === 0
          ? this.currentAmortization.installment +
            this.calculateForfeit(this.currentAmortization) -
            this.amountReceived
          : this.totalDebtAmount - this.amountReceived;
    },
    paymentDate: function () {
      this.diffDays = moment(this.paymentDate).diff(
        this.currentAmortization.dueDate,
        "days"
      );

      const forfeitValue =
        this.currentAmortization.installment * (this.company.forfeit / 100);
      this.forfeitValue = this.diffDays > 0 ? forfeitValue * this.diffDays : 0;
      this.total2Pay = this.forfeitValue + this.currentAmortization.installment;
      this.totalDebtAmount = this.total2Pay;
      this.amountReceived = this.total2Pay;
    },
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "currentCustomer",
      "customerTranzactions",
      "company",
    ]),
  },

  methods: {
    getAmortizationLoans() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(
          `/api/loan/amortization/${this.currentLoan.id}/${this.company.forfeit}`
        )
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.paidAmortizations = data.result.filter((ammort) => {
              return ammort.status === 1;
            });
            this.customerLoanAmortization = data.result.filter((ammort) => {
              return ammort.status <= 0;
            });
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.customerLoanAmortization = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.customerLoanAmortization = [];
        });
    },

    getLoanDebts() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/debt/${this.currentLoan.id}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.loanDebts = data.result;
          } else {
            this.showToast("Erro!", "danger", data.message);
            this.loanDebts = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.loanDebts = [];
        });
    },

    getTotalDebt(amortization) {
      const debt = this.loanDebts.filter((a) => {
        return a.amortisationId === amortization.id;
      });
      this.currentDebt = debt.length > 0 ? debt[0] : [];
      const total = debt.length > 0 ? debt[0].debtAmount : 0;
      const diffDays = moment(this.paymentDate).diff(
        debt.length > 0 ? debt[0].updatedAt : moment(),
        "days"
      );

      const forfeit = total * (this.company.forfeit / 100);
      const totalForfeit = diffDays > 0 ? forfeit * diffDays : 0;
      this.totalAmortizationForfeit = totalForfeit;
      this.totalDebtAmount = totalForfeit + total;
      return total + totalForfeit;
    },

    payDebt() {
      console.log(this.currentDebt);
      this.$refs["place-debt-payment"].show();
      this.debitBalance = 0;
      this.paymentReference = `${this.currentCustomer.accountNumber}PY${this.currentDebt.amortisationId}`;
      this.paymentMethod = 1;
      this.amountReceived = this.totalDebtAmount;
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    calculateForfeit(amortization) {
      const diffDays = moment(this.paymentDate).diff(
        amortization.dueDate,
        "days"
      );
      const forfeitValue =
        amortization.installment * (this.company.forfeit / 100);
      return diffDays >= 0 ? forfeitValue * diffDays : 0;
    },

    editAmortization(amortization) {
      alert(amortization.id);
    },

    async previewReceipt(amortization) {
      const tranzactions = this.customerTranzactions.filter((a) => {
        return a.amortizationLoanId === amortization.id;
      });

      const payments = AmmortizationPlan.getPaymentBody(tranzactions);

      const ammortizationLoans = AmmortizationPlan.getAmmortizationLoans(
        this.customerLoanAmortization
      );

      let docDefinition = {
        footer: {
          columns: [
            {
              text: "Documento processado por computador",
              alignment: "left",
              fontSize: 7,
              margin: [30, 0, 0, 0],
            },
            {
              text: this.company.smsSender,
              alignment: "right",
              fontSize: 7,
              margin: [0, 0, 30, 0],
            },
          ],
        },

        header: {
          columns: [
            // COMPANY DETAILS
            {
              image: companyLogo.getLogo(),
              width: 100,
            },
            {
              text: `
                ${this.company.companyAddress}\n
                Telefone: +${this.company.companyPhone} | E-mail: ${this.company.companyEmail} | NUIT: ${this.company.companyNuit}
                `,
              fontSize: 8,
              alignment: "left",
            },
          ],
        },

        content: [
          { text: "\n\n\n\n" },
          {
            text: `RECIBO\n#${tranzactions[0].id} \n`,
            fontSize: 9,
            bold: true,
          },
          {
            text: `Data: ${DateFormat.formatDate(tranzactions[0].createdAt)}`,
            fontSize: 8,
          },
          { text: "\n\n" },
          {
            text: `Para:\n\n${this.currentCustomer.customerName.toUpperCase()}`,
            fontSize: 9,
            bold: true,
          },
          {
            text: `Nº do cliente: ${this.currentCustomer.accountNumber}`,
            fontSize: 9,
            bold: true,
          },
          {
            text: `${this.currentCustomer.customerAddress}`,
            fontSize: 8,
          },
          {
            text: `Cell: ${this.currentCustomer.customerPhone}`,
            fontSize: 8,
          },
          {
            text: `NUIT: ${this.currentCustomer.customerNuit}`,
            fontSize: 8,
          },
          { text: "\n" },
          {
            text: `${tranzactions[0].description}\n`,
            fontSize: 9,
            alignment: "center",
          },
          { text: "\n" },
          {
            table: {
              widths: ["*", "*", "auto", "auto", "auto", "auto", "auto"],
              body: [
                [
                  { text: "Data de pagamento", style: "columnsTitle" },
                  {
                    text: "Meio de pagamento",
                    style: "columnsTitle",
                    alignment: "left",
                  },
                  { text: "Referência", style: "columnsTitle" },
                  { text: "Capital", style: "columnsTitle" },
                  { text: "Juros", style: "columnsTitle" },
                  { text: "Juros de mora", style: "columnsTitle" },
                  { text: `Total pago`, style: "columnsTitle" },
                ],
                ...payments,
              ],
            },
            layout: "lightHorizontalLines",
          },
          { text: "\nPróximos pagamentos\n", fontSize: 9, bold: true },
          {
            table: {
              widths: ["auto", "*", "auto", "auto", "auto", "auto", "auto"],
              body: [
                [
                  { text: "#", style: "columnsTitle" },
                  { text: "Data de pagamento", style: "columnsTitle" },
                  { text: "Capital", style: "columnsTitle" },
                  { text: "Juros", style: "columnsTitle" },
                  { text: "Juros de mora", style: "columnsTitle" },
                  { text: `Total`, style: "columnsTitle" },
                  { text: `Status`, style: "columnsTitle" },
                ],
                ...ammortizationLoans,
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],

        styles: {
          columnsTitle: {
            fontSize: 8,
            bold: true,
            color: "#000000",
          },
        },
      };

      // pdfMake.createPdf(docDefinition).download(`proforma${this.currentQuotation.name}.pdf`);
      pdfMake.createPdf(docDefinition).open();
    },

    addPayment(amortization) {
      this.currentAmortization = amortization;
      this.$refs["place-payment"].show();
      this.debitBalance = 0;
      this.paymentReference = `${this.currentCustomer.accountNumber}PY${amortization.id}`;
      this.paymentMethod = 1;
      this.phoneNumber = this.currentCustomer.customerPhone;
      this.amortizationLoanId = amortization.id;
      this.installmentOrder = amortization.installmentOrder;
      this.amountReceived =
        amortization.latePaymentInterest + amortization.installment;
      this.total2Pay =
        amortization.latePaymentInterest + amortization.installment;
      this.diffDays = amortization.lateDays;

      this.forfeitValue =
        this.diffDays > 0 ? amortization.latePaymentInterest : 0;
    },

    payViaMpesa() {
      if (this.phoneNumber.length != 12) {
        this.showToast("Avizo!", "warning", "O número que digitou é inválido.");
        return;
      } else {
        const passingValues = {
          from: this.phoneNumber + "",
          reference: this.currentCustomer.accountNumber + "",
          amount: this.amountReceived + "",
          transaction:
            this.currentCustomer.accountNumber + "PY" + this.amortizationLoanId,
          loanId: this.currentLoan.loanId,
          paymentDate: this.paymentDate,
        };

        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/mpesa/receive`, passingValues)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              const response = data.result;
              if (
                response.output_ResponseDesc == "Request processed successfully"
              ) {
                this.showToast(
                  "Sucesso!",
                  "success",
                  "Pagamento efectuado com sucesso."
                );
                this.addTransaction(response);
              }
            } else {
              this.showToast("Erro!", "danger", data.message);
              const response = data.result;
              if (response.output_ResponseDesc == "Duplicate Transaction") {
                this.showToast(
                  "Erro!",
                  "danger",
                  "Tranzação duplicada, tente mais tarde"
                );
              }
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
            console.log(err);
          });
      }
    },

    addTransaction(mpesa) {
      const passingValues = {
        tranzactionReference: mpesa.output_TransactionID.toUpperCase(),
        accountNumber: this.currentCustomer.accountNumber,
        phoneNumber: this.phoneNumber,
        staffName: this.user.name,
        companyId: this.company.id,
        amount: this.amountReceived,
        latePaymentInterest: this.calculateForfeit(this.currentAmortization),
        interestRateAmount: this.currentAmortization.rateAmount,
        paymentMethod: this.paymentMethod,
        loanId: this.currentAmortization.loanId,
        paymentDate: this.paymentDate,
        amortizationLoanId: this.amortizationLoanId,
        receiptUrl: this.receiptUrl,
        description: `Recebemos ${MoneyFormat.formatMoney(
          this.amountReceived
        )}, referente ao pagamento da ${
          this.installmentOrder
        } com a referência ${mpesa.output_TransactionID.toUpperCase()}.`,
      };

      this.$store.commit("LOADING_STATUS", true);
      axios
        .post(`/api/tranzaction`, passingValues)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast(
              "Sucesso!",
              "success",
              "Pagamento efectuado com sucesso"
            );
            const logsParams = logs(
              this.user,
              `${passingValues.description}`,
              "Desembolso de crédito"
            );
            this.$store.dispatch("addLog", logsParams);
            if (parseFloat(this.debitBalance) > 0) this.insertDebt();
          } else {
            this.showToast("Erro!", "danger", data.message);
          }
          this.getAmortizationLoans();
          this.getLoanDebts();
          this.getCustomerTranzactions();
          this.$refs["place-payment"].hide();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["place-payment"].hide();
        });
    },

